const LOAN_DAYS = 21;
const MAX_LOANS = 5;
const BORROW_BLOCK_OWED = 1000;
const FINE_PER_DAY = 25;
const GRACE_DAYS = 2;
const FINE_CAP = 500;
const MAX_RENEWALS = 2;
const HOLD_PICKUP_DAYS = 3;
const DAY_MS = 86400000;

function parseDate(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const [y, m, d] = s.split('-').map(Number);
  const t = Date.UTC(y, m - 1, d);
  const dt = new Date(t);
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
  return Math.round(t / DAY_MS);
}

function formatDay(n) {
  const dt = new Date(n * DAY_MS);
  const y = String(dt.getUTCFullYear()).padStart(4, '0');
  const m = String(dt.getUTCMonth() + 1).padStart(2, '0');
  const d = String(dt.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function addDays(s, n) {
  return formatDay(parseDate(s) + n);
}

function validId(id) {
  return id !== undefined && id !== null;
}

const fail = (reason) => ({ ok: false, reason });

export function createLibrary() {
  // bookId -> { loan: { memberId, dueDate, renewals } | null, holds: [memberId], readyUntil: string|null }
  const books = new Map();
  // memberId -> { owed }
  const members = new Map();

  function advance(date) {
    const today = parseDate(date);
    for (const book of books.values()) {
      while (book.readyUntil !== null && today > parseDate(book.readyUntil)) {
        const old = book.readyUntil;
        book.holds.shift();
        book.readyUntil = book.holds.length > 0 ? addDays(old, HOLD_PICKUP_DAYS) : null;
      }
    }
  }

  function loansOf(memberId) {
    const result = [];
    for (const [bookId, book] of books) {
      if (book.loan && book.loan.memberId === memberId) result.push({ bookId, dueDate: book.loan.dueDate });
    }
    return result;
  }

  function addBook({ bookId } = {}) {
    if (!validId(bookId)) return fail('invalid bookId');
    if (books.has(bookId)) return fail('book exists');
    books.set(bookId, { loan: null, holds: [], readyUntil: null });
    return { ok: true };
  }

  function addMember({ memberId } = {}) {
    if (!validId(memberId)) return fail('invalid memberId');
    if (members.has(memberId)) return fail('member exists');
    members.set(memberId, { owed: 0 });
    return { ok: true };
  }

  function borrow({ memberId, bookId, date } = {}) {
    if (parseDate(date) === null) return fail('invalid date');
    advance(date);
    const member = members.get(memberId);
    const book = books.get(bookId);
    if (!member) return fail('unknown member');
    if (!book) return fail('unknown book');
    if (member.owed >= BORROW_BLOCK_OWED) return fail('owes too much');
    if (book.loan) return fail('book on loan');
    if (loansOf(memberId).length >= MAX_LOANS) return fail('too many loans');
    if (book.readyUntil !== null) {
      if (book.holds[0] !== memberId) return fail('set aside for another member');
      book.holds.shift();
      book.readyUntil = null;
    }
    const dueDate = addDays(date, LOAN_DAYS);
    book.loan = { memberId, dueDate, renewals: 0 };
    return { ok: true, dueDate };
  }

  function returnBook({ memberId, bookId, date } = {}) {
    if (parseDate(date) === null) return fail('invalid date');
    advance(date);
    const member = members.get(memberId);
    const book = books.get(bookId);
    if (!member || !book || !book.loan || book.loan.memberId !== memberId) {
      return fail('not on loan to member');
    }
    const daysLate = parseDate(date) - parseDate(book.loan.dueDate);
    let fine = 0;
    if (daysLate > GRACE_DAYS) fine = Math.min(daysLate * FINE_PER_DAY, FINE_CAP);
    member.owed += fine;
    book.loan = null;
    if (book.holds.length > 0) book.readyUntil = addDays(date, HOLD_PICKUP_DAYS);
    return { ok: true, fine };
  }

  function renew({ memberId, bookId, date } = {}) {
    if (parseDate(date) === null) return fail('invalid date');
    advance(date);
    const book = books.get(bookId);
    if (!members.has(memberId) || !book || !book.loan || book.loan.memberId !== memberId) {
      return fail('not on loan to member');
    }
    if (book.loan.renewals >= MAX_RENEWALS) return fail('renewal limit');
    if (book.holds.length > 0) return fail('book has holds');
    if (parseDate(date) > parseDate(book.loan.dueDate)) return fail('overdue');
    book.loan.dueDate = addDays(book.loan.dueDate, LOAN_DAYS);
    book.loan.renewals += 1;
    return { ok: true, dueDate: book.loan.dueDate };
  }

  function placeHold({ memberId, bookId, date } = {}) {
    if (parseDate(date) === null) return fail('invalid date');
    advance(date);
    const book = books.get(bookId);
    if (!members.has(memberId) || !book) return fail('unknown member or book');
    if (!book.loan && book.readyUntil === null) return fail('book is on shelf');
    if (book.loan && book.loan.memberId === memberId) return fail('member has book');
    if (book.holds.includes(memberId)) return fail('already holding');
    book.holds.push(memberId);
    return { ok: true, position: book.holds.length };
  }

  function payFine({ memberId, amount, date } = {}) {
    if (date !== undefined) {
      if (parseDate(date) === null) return fail('invalid date');
      advance(date);
    }
    const member = members.get(memberId);
    if (!member) return fail('unknown member');
    if (typeof amount !== 'number' || !Number.isInteger(amount) || amount <= 0) return fail('invalid amount');
    if (amount > member.owed) return fail('overpayment');
    member.owed -= amount;
    return { ok: true, owed: member.owed };
  }

  function getMember({ memberId, date } = {}) {
    if (date !== undefined) {
      if (parseDate(date) === null) return fail('invalid date');
      advance(date);
    }
    const member = members.get(memberId);
    if (!member) return fail('unknown member');
    const holds = [];
    for (const [bookId, book] of books) {
      const idx = book.holds.indexOf(memberId);
      if (idx === -1) continue;
      holds.push({
        bookId,
        position: idx + 1,
        readyUntil: idx === 0 && book.readyUntil !== null ? book.readyUntil : null,
      });
    }
    return { ok: true, loans: loansOf(memberId), owed: member.owed, holds };
  }

  return { addBook, addMember, borrow, returnBook, renew, placeHold, payFine, getMember };
}
